   RedRoom Fitness — Global Stylesheet
   Dark, Bold, Premium HIIT Brand
   ============================================ */

@import url('https://fonts.googleapis.com/css2?family=Oswald:wght@400;500;600;700&family=Inter:wght@300;400;500;600;700&family=Bebas+Neue&display=swap');

/* --- CSS Custom Properties --- */
:root {
  --red: #FF0000;
  --red-hover: #cc0000;
  --red-glow: rgba(255, 0, 0, 0.3);
  --black: #141414;
  --black-alt: #1a1a1a;
  --black-light: #222222;
  --dark-card: #1e1e1e;
  --white: #FFFFFF;
  --gray-100: #F5F5F5;
  --gray-200: #E5E5E5;
  --gray-300: #D4D4D4;
  --gray-400: #A3A3A3;
  --gray-500: #737373;
  --gray-600: #525252;
  --gray-700: #404040;
  --gray-800: #262626;
  --font-display: 'Bebas Neue', 'Oswald', sans-serif;
  --font-heading: 'Oswald', sans-serif;
  --font-body: 'Inter', 'Helvetica Neue', sans-serif;
  --radius: 0.5rem;
  --radius-lg: 1rem;
  --transition: 200ms ease;
  --transition-slow: 350ms ease;
  --max-width: 1280px;
}

/* --- Reset & Base --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  background-color: var(--black);
  color: var(--white);
  line-height: 1.6;
  overflow-x: hidden;
  min-height: 100vh;
}

img { max-width: 100%; height: auto; display: block; }
a { color: inherit; text-decoration: none; }
button { cursor: pointer; font-family: inherit; border: none; background: none; }
ul, ol { list-style: none; }
input, select { font-family: inherit; }

.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 1.5rem;
}

/* ============================================
   TOP PROMO BAR
   ============================================ */
.promo-bar {
  background: var(--red);
  color: var(--white);
  text-align: center;
  padding: 0.625rem 1.5rem;
  font-size: 0.8125rem;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  flex-wrap: wrap;
}
.promo-bar a {
  text-decoration: underline;
  text-underline-offset: 2px;
  font-weight: 700;
  transition: opacity var(--transition);
}
.promo-bar a:hover { opacity: 0.8; }

/* ============================================
   NAVIGATION
   ============================================ */
.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--black);
  border-bottom: 1px solid rgba(255,255,255,0.08);
  transition: background var(--transition);
}
.nav.scrolled {
  background: rgba(20, 20, 20, 0.95);
  backdrop-filter: blur(12px);
}
.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1rem 1.5rem;
  max-width: var(--max-width);
  margin: 0 auto;
}
.nav-logo {
  font-family: var(--font-display);
  font-size: 1.75rem;
  letter-spacing: -0.02em;
  color: var(--red);
  text-transform: uppercase;
  flex-shrink: 0;
}
.nav-logo span { color: var(--white); }
.nav-links {
  display: flex;
  align-items: center;
  gap: 2rem;
}
.nav-links a {
  font-size: 0.8125rem;
  font-weight: 500;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--gray-400);
  transition: color var(--transition);
  position: relative;
}
.nav-links a:hover,
.nav-links a.active {
  color: var(--white);
}
.nav-links a.active::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--red);
}
.nav-cta {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}
.nav-cta .btn { font-size: 0.75rem; padding: 0.5rem 1rem; }
.nav-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 4px;
}
.nav-toggle span {
  width: 24px;
  height: 2px;
  background: var(--white);
  transition: all var(--transition);
}
.nav-toggle.active span:nth-child(1) { transform: rotate(45deg) translate(5px, 5px); }
.nav-toggle.active span:nth-child(2) { opacity: 0; }
.nav-toggle.active span:nth-child(3) { transform: rotate(-45deg) translate(5px, -5px); }

/* ============================================
   BUTTONS
   ============================================ */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.75rem 1.75rem;
  font-family: var(--font-heading);
  font-size: 0.875rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  border-radius: var(--radius);
  transition: all var(--transition);
  white-space: nowrap;
}
.btn-primary {
  background: var(--red);
  color: var(--white);
  box-shadow: 0 0 20px rgba(255, 0, 0, 0.25);
}
.btn-primary:hover {
  background: var(--red-hover);
  box-shadow: 0 0 30px rgba(255, 0, 0, 0.4);
  transform: translateY(-1px);
}
.btn-outline {
  border: 2px solid var(--white);
  color: var(--white);
  background: transparent;
}
.btn-outline:hover {
  background: var(--white);
  color: var(--black);
}
.btn-dark {
  background: var(--white);
  color: var(--black);
}
.btn-dark:hover {
  background: var(--gray-200);
  transform: translateY(-1px);
}
.btn-lg {
  padding: 1rem 2.5rem;
  font-size: 1rem;
}

/* ============================================
   SECTIONS — Shared
   ============================================ */
.section {
  padding: 5rem 0;
  position: relative;
}
.section-dark { background: var(--black); }
.section-alt { background: var(--black-alt); }
.section-light { background: var(--black-light); }
.section-red { background: var(--red); }

.section-label {
  font-family: var(--font-heading);
  font-size: 0.75rem;
  font-weight: 500;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--red);
  margin-bottom: 0.75rem;
  display: block;
}
.section-title {
  font-family: var(--font-display);
  font-size: clamp(2.5rem, 5vw, 4.5rem);
  line-height: 1.05;
  text-transform: uppercase;
  letter-spacing: -0.01em;
  margin-bottom: 1.5rem;
  color: var(--white);
}
.section-subtitle {
  font-size: 1.125rem;
  color: var(--gray-400);
  max-width: 640px;
  line-height: 1.7;
}
.text-red { color: var(--red); }
.text-center { text-align: center; }
.mx-auto { margin-left: auto; margin-right: auto; }

/* ============================================
   HERO SECTION
   ============================================ */
.hero {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  background: var(--black);
  overflow: hidden;
}
.hero-bg {
  position: absolute;
  inset: 0;
  z-index: 0;
}
.hero-bg img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0.35;
}
.hero-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    180deg,
    rgba(20, 20, 20, 0.4) 0%,
    rgba(20, 20, 20, 0.85) 70%,
    var(--black) 100%
  );
  z-index: 1;
}
.hero-content {
  position: relative;
  z-index: 2;
  max-width: 800px;
}
.hero-content .section-title {
  font-size: clamp(3rem, 7vw, 6rem);
  margin-bottom: 1.25rem;
  line-height: 1;
}
.hero-content .section-subtitle {
  font-size: 1.15rem;
  margin-bottom: 2.5rem;
  color: var(--gray-300);
}
.hero-actions {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}

/* ============================================
   LIFESTYLE CAROUSEL
   ============================================ */
.carousel {
  position: relative;
  overflow: hidden;
  border-radius: var(--radius-lg);
}
.carousel-track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.25, 0.1, 0.25, 1);
}
.carousel-slide {
  min-width: 100%;
  aspect-ratio: 16 / 9;
}
.carousel-slide img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: var(--radius-lg);
}
.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  z-index: 10;
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: rgba(0,0,0,0.6);
  border: 1px solid rgba(255,255,255,0.2);
  color: var(--white);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  transition: all var(--transition);
  backdrop-filter: blur(8px);
}
.carousel-btn:hover {
  background: var(--red);
  border-color: var(--red);
}
.carousel-prev { left: 1rem; }
.carousel-next { right: 1rem; }
.carousel-dots {
  display: flex;
  gap: 0.5rem;
  justify-content: center;
  margin-top: 1rem;
}
.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--gray-600);
  transition: all var(--transition);
}
.carousel-dot.active {
  background: var(--red);
  box-shadow: 0 0 8px var(--red-glow);
}

/* ============================================
   TWO WAYS — Card Grid
   ============================================ */
.two-ways-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
  margin-top: 2.5rem;
}
.way-card {
  background: var(--dark-card);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: var(--radius-lg);
  padding: 3rem 2.5rem;
  transition: all var(--transition-slow);
  position: relative;
  overflow: hidden;
}
.way-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: var(--red);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform var(--transition-slow);
}
.way-card:hover {
  border-color: rgba(255,255,255,0.12);
  transform: translateY(-4px);
}
.way-card:hover::before { transform: scaleX(1); }
.way-card-icon {
  width: 56px;
  height: 56px;
  background: rgba(255, 0, 0, 0.1);
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  margin-bottom: 1.5rem;
}
.way-card h3 {
  font-family: var(--font-display);
  font-size: 2rem;
  text-transform: uppercase;
  letter-spacing: 0.02em;
  margin-bottom: 0.75rem;
}
.way-card p {
  color: var(--gray-400);
  line-height: 1.7;
}

/* ============================================
   FLOOR/TREADMILL TOGGLE
   ============================================ */
.toggle-wrapper {
  display: flex;
  gap: 0;
  margin-bottom: 2.5rem;
  background: var(--black-light);
  border-radius: var(--radius);
  padding: 0.375rem;
  width: fit-content;
}
.toggle-btn {
  padding: 0.75rem 2rem;
  font-family: var(--font-heading);
  font-size: 0.875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--gray-400);
  border-radius: var(--radius);
  transition: all var(--transition);
}
.toggle-btn.active {
  background: var(--red);
  color: var(--white);
  box-shadow: 0 0 15px var(--red-glow);
}
.toggle-content {
  display: none;
  animation: fadeSlideIn 400ms ease-out;
}
.toggle-content.active { display: block; }

@keyframes fadeSlideIn {
  from { opacity: 0; transform: translateY(12px); }
  to { opacity: 1; transform: translateY(0); }
}

/* ============================================
   WEEKLY SCHEDULE TABLE
   ============================================ */
.schedule-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 2rem;
}
.schedule-table th,
.schedule-table td {
  padding: 1rem 1.5rem;
  text-align: left;
  border-bottom: 1px solid rgba(255,255,255,0.06);
}
.schedule-table th {
  font-family: var(--font-heading);
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--gray-400);
  background: rgba(255,255,255,0.03);
}
.schedule-table tr {
  transition: background var(--transition);
}
.schedule-table tbody tr:hover {
  background: rgba(255, 0, 0, 0.05);
}
.schedule-table .day-badge {
  display: inline-block;
  background: var(--red);
  color: var(--white);
  font-weight: 700;
  padding: 0.25rem 0.75rem;
  border-radius: 999px;
  font-size: 0.75rem;
  text-transform: uppercase;
}
.schedule-day-off {
  color: var(--gray-600);
  font-style: italic;
}

/* ============================================
   FAQ ACCORDION
   ============================================ */
.faq-list {
  max-width: 800px;
  margin: 0 auto;
}
.faq-item {
  border-bottom: 1px solid rgba(255,255,255,0.08);
}
.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.5rem 0;
  font-family: var(--font-heading);
  font-size: 1.125rem;
  font-weight: 500;
  text-align: left;
  color: var(--white);
  transition: color var(--transition);
  gap: 1rem;
}
.faq-question:hover { color: var(--red); }
.faq-icon {
  flex-shrink: 0;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  border: 2px solid var(--gray-500);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  transition: all var(--transition);
  position: relative;
}
.faq-icon::before {
  content: '+';
  transition: transform var(--transition);
}
.faq-item.open .faq-icon {
  border-color: var(--red);
  background: var(--red);
}
.faq-item.open .faq-icon::before {
  content: '−';
}
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease, padding 0.4s ease;
}
.faq-item.open .faq-answer {
  max-height: 300px;
  padding-bottom: 1.5rem;
}
.faq-answer p {
  color: var(--gray-400);
  line-height: 1.7;
  padding-right: 3rem;
}

/* ============================================
   INSTRUCTOR GRID & FILTERS
   ============================================ */
.filter-bar {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
  margin-bottom: 3rem;
  justify-content: center;
}
.filter-btn {
  padding: 0.5rem 1.25rem;
  font-size: 0.8125rem;
  font-weight: 500;
  color: var(--gray-400);
  background: var(--black-light);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: 999px;
  transition: all var(--transition);
  text-transform: uppercase;
  letter-spacing: 0.03em;
}
.filter-btn:hover {
  color: var(--white);
  border-color: rgba(255,255,255,0.2);
}
.filter-btn.active {
  background: var(--red);
  color: var(--white);
  border-color: var(--red);
  box-shadow: 0 0 12px var(--red-glow);
}
.instructor-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 1.5rem;
}
.instructor-card {
  background: var(--dark-card);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: all var(--transition-slow);
}
.instructor-card:hover {
  border-color: rgba(255,0,0,0.3);
  transform: translateY(-4px);
}
.instructor-card.fade-out {
  opacity: 0.25;
  transform: scale(0.95);
}
.instructor-img {
  aspect-ratio: 1;
  background: var(--black-light);
  position: relative;
  overflow: hidden;
}
.instructor-img img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform var(--transition-slow);
}
.instructor-card:hover .instructor-img img {
  transform: scale(1.05);
}
.instructor-info {
  padding: 1.5rem;
}
.instructor-info h3 {
  font-family: var(--font-display);
  font-size: 1.75rem;
  text-transform: uppercase;
  letter-spacing: 0.02em;
  margin-bottom: 0.25rem;
}
.instructor-location {
  font-size: 0.8125rem;
  color: var(--gray-500);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 1rem;
}
.instructor-info .btn {
  width: 100%;
  font-size: 0.75rem;
}

/* ============================================
   FREE TRIAL CTA
   ============================================ */
.cta-section {
  background: var(--red);
  text-align: center;
  padding: 4rem 1.5rem;
}
.cta-section .section-title {
  color: var(--white);
  font-size: clamp(2rem, 4.5vw, 3.5rem);
}
.cta-section .section-subtitle {
  color: rgba(255,255,255,0.85);
  max-width: 600px;
  margin: 0 auto 2rem;
}

/* ============================================
   NEWSLETTER
   ============================================ */
.newsletter {
  background: var(--black-alt);
  padding: 4rem 1.5rem;
  text-align: center;
}
.newsletter-inner {
  max-width: 540px;
  margin: 0 auto;
}
.newsletter h3 {
  font-family: var(--font-display);
  font-size: 2.25rem;
  text-transform: uppercase;
  letter-spacing: 0.02em;
  margin-bottom: 0.75rem;
}
.newsletter p {
  color: var(--gray-400);
  margin-bottom: 1.5rem;
  font-size: 0.9375rem;
}
.newsletter-form {
  display: flex;
  gap: 0.75rem;
}
.newsletter-form input {
  flex: 1;
  padding: 0.875rem 1.25rem;
  background: var(--black-light);
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: var(--radius);
  color: var(--white);
  font-size: 0.9375rem;
  transition: border-color var(--transition);
  outline: none;
}
.newsletter-form input:focus {
  border-color: var(--red);
}
.newsletter-form input.error {
  border-color: var(--red);
}
.newsletter-form .btn {
  flex-shrink: 0;
}
.newsletter-error {
  color: var(--red);
  font-size: 0.8125rem;
  margin-top: 0.5rem;
  text-align: left;
  display: none;
}
.newsletter-error.visible { display: block; }
.newsletter-success {
  color: #4ade80;
  font-size: 0.9375rem;
  margin-top: 1rem;
  display: none;
}
.newsletter-success.visible { display: block; }

/* ============================================
   FOOTER
   ============================================ */
.footer {
  background: var(--black);
  border-top: 1px solid rgba(255,255,255,0.06);
  padding: 4rem 1.5rem 2rem;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2.5rem;
  margin-bottom: 3rem;
}
.footer-col h4 {
  font-family: var(--font-heading);
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--gray-400);
  margin-bottom: 1.25rem;
}
.footer-col a {
  display: block;
  color: var(--gray-500);
  font-size: 0.875rem;
  padding: 0.375rem 0;
  transition: color var(--transition);
}
.footer-col a:hover { color: var(--white); }
.footer-col select {
  width: 100%;
  padding: 0.625rem 0.75rem;
  background: var(--black-light);
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: var(--radius);
  color: var(--white);
  font-size: 0.875rem;
  outline: none;
  cursor: pointer;
  margin-top: 0.5rem;
}
.footer-col select:focus { border-color: var(--red); }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.06);
  padding-top: 1.5rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
}
.footer-bottom p {
  color: var(--gray-600);
  font-size: 0.8125rem;
}
.footer-social {
  display: flex;
  gap: 1rem;
}
.footer-social a {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  border: 1px solid rgba(255,255,255,0.08);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--gray-500);
  transition: all var(--transition);
  font-size: 0.875rem;
}
.footer-social a:hover {
  border-color: var(--red);
  color: var(--red);
}

/* ============================================
   FEATURE CARDS (Digital Platform)
   ============================================ */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 1.5rem;
  margin-top: 2.5rem;
}
.feature-card {
  background: var(--dark-card);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: var(--radius-lg);
  padding: 2rem;
  transition: all var(--transition);
}
.feature-card:hover {
  border-color: rgba(255,0,0,0.2);
  transform: translateY(-2px);
}
.feature-card .feature-icon {
  font-size: 2rem;
  margin-bottom: 1rem;
  display: block;
}
.feature-card h3 {
  font-family: var(--font-display);
  font-size: 1.5rem;
  text-transform: uppercase;
  letter-spacing: 0.02em;
  margin-bottom: 0.5rem;
}
.feature-card p {
  color: var(--gray-400);
  font-size: 0.9375rem;
  line-height: 1.6;
}

/* ============================================
   STUDIO EXPERIENCE SECTION
   ============================================ */
.studio-section {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}
.studio-image {
  aspect-ratio: 4/3;
  border-radius: var(--radius-lg);
  overflow: hidden;
  position: relative;
}
.studio-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.studio-image::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at center, transparent 55%, rgba(20,20,20,0.7) 100%);
}
.studio-content .section-title {
  font-size: clamp(2rem, 4vw, 3.5rem);
}

/* ============================================
   COMMUNITY PROMO SECTION
   ============================================ */
.community-promo {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}
.community-image {
  aspect-ratio: 4/3;
  border-radius: var(--radius-lg);
  overflow: hidden;
}
.community-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.community-content .section-title {
  font-size: clamp(2rem, 4vw, 3.5rem);
}

/* ============================================
   ANIMATIONS
   ============================================ */
.fade-up {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 600ms ease-out, transform 600ms ease-out;
}
.fade-up.visible {
  opacity: 1;
  transform: translateY(0);
}

/* ============================================
   RESPONSIVE
   ============================================ */
@media (max-width: 1024px) {
  .two-ways-grid { grid-template-columns: 1fr; }
  .studio-section { grid-template-columns: 1fr; gap: 2rem; }
  .community-promo { grid-template-columns: 1fr; gap: 2rem; }
  .community-image { order: -1; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  .nav-links,
  .nav-cta { display: none; }
  .nav-links.open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: 100%;
    left: 0;
    right: 0;
    background: var(--black);
    border-bottom: 1px solid rgba(255,255,255,0.08);
    padding: 1.5rem;
    gap: 1.25rem;
  }
  .nav-cta.open {
    display: flex;
    flex-direction: column;
    padding: 0 1.5rem 1.5rem;
    background: var(--black);
    position: absolute;
    top: calc(100% + 280px);
    left: 0;
    right: 0;
    gap: 0.75rem;
  }
  .nav-toggle { display: flex; }
  .hero { min-height: 70vh; }
  .hero-content { text-align: center; }
  .hero-actions { justify-content: center; }
  .section { padding: 3.5rem 0; }
  .instructor-grid { grid-template-columns: repeat(auto-fill, minmax(240px, 1fr)); }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .newsletter-form { flex-direction: column; }
  .features-grid { grid-template-columns: 1fr; }
}

@media (max-width: 480px) {
  .container { padding: 0 1rem; }
  .hero-content .section-title { font-size: 2.25rem; }
  .hero-actions { flex-direction: column; }
  .hero-actions .btn { width: 100%; }
  .section-title { font-size: 2rem; }
  .footer-grid { grid-template-columns: 1fr; }
  .toggle-wrapper { flex-direction: column; width: 100%; }
  .footer-bottom { flex-direction: column; text-align: center; }
  .carousel-btn { width: 36px; height: 36px; font-size: 1rem; }
}
